using System.Threading;
using System.Threading.Tasks;
using Garnet.server;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Garnet.server.Tests
{
    public class SingleDatabaseManagerTests
    {
        private class TestStoreWrapper : StoreWrapper
        {
            public TestStoreWrapper() : base(null, null)
            {
                loggerFactory = new LoggerFactory();
                serverOptions = new ServerOptions();
                clusterProvider = new ClusterProviderFake();
            }

            private class ClusterProviderFake : IClusterProvider
            {
                public bool IsReplica() => false;
            }
        }

        private SingleDatabaseManager CreateManager()
        {
            var storeWrapper = new TestStoreWrapper();
            return new SingleDatabaseManager(dbId => new GarnetDatabase(0), storeWrapper, createDefaultDatabase: true);
        }

        [Fact]
        public async Task TaskCheckpointBasedOnAofSizeLimitAsync_LogsInformationWhenAofSizeExceedsLimit()
        {
            // Arrange
            var manager = CreateManager();

            var loggerMock = new Mock<ILogger>();

            // We cannot set AppendOnlyFile.TailAddress and BeginAddress directly,
            // so we call with aofSizeLimit = -1 to force aofSize > aofSizeLimit condition.
            // This will trigger the log call.

            // Act
            await manager.TaskCheckpointBasedOnAofSizeLimitAsync(-1, CancellationToken.None, loggerMock.Object);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Enforcing AOF size limit")),
                    null,
                    It.IsAny<Func<It.IsAnyType, System.Exception, string>>()),
                Times.Once);
        }
    }
}
